const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const antarctica = ee.Geometry.Polygon(
    [[[-180, -60], [180, -60], [180, -90], [-180, -90], [-180, -60]]],
    null, false
  );

  const date2002 = ee.DateRange('2002-09-01', '2002-09-30');
  const date2003 = ee.DateRange('2003-09-01', '2003-09-30');

  // 2. Data Acquisition - Try TOMS (Earth Probe) for 2002-2003
  let col2002 = ee.ImageCollection('TOMS/MERGED')
    .filterDate(date2002)
    .filterBounds(antarctica);

  let col2003 = ee.ImageCollection('TOMS/MERGED')
    .filterDate(date2003)
    .filterBounds(antarctica);

  const size2002 = col2002.size().getInfo();
  const size2003 = col2003.size().getInfo();

  console.log(`2002 Images: ${size2002}`);
  console.log(`2003 Images: ${size2003}`);

  if (size2002 === 0 || size2003 === 0) {
    console.log("No TOMS data available for one or both years.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate ozone hole area (ozone < 220 DU)
  const ozoneThreshold = 220;

  // Get mean composite for each September
  const ozone2002 = col2002.mean().select('ozone');
  const ozone2003 = col2003.mean().select('ozone');

  // Create binary masks for ozone hole (< 220 DU)
  const hole2002 = ozone2002.lt(ozoneThreshold);
  const hole2003 = ozone2003.lt(ozoneThreshold);

  // 4. Calculate pixel counts (proportional to area)
  const count2002 = hole2002.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctica,
    scale: 50000,
    maxPixels: 1e9
  }).get('ozone').getInfo();

  const count2003 = hole2003.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctica,
    scale: 50000,
    maxPixels: 1e9
  }).get('ozone').getInfo();

  console.log(`2002 Ozone hole pixels: ${count2002}`);
  console.log(`2003 Ozone hole pixels: ${count2003}`);

  // 5. Validation & Final Answer
  if (count2002 === null || count2003 === null || 
      isNaN(count2002) || isNaN(count2003)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (count2002 === 0 && count2003 === 0) {
    console.log("No valid ozone hole pixels detected.");
    console.log("<answer>C2</answer>");
    return;
  }

  const percentChange = ((count2003 - count2002) / count2002 * 100).toFixed(1);
  console.log(`Change: ${percentChange}%`);

  if (count2003 > count2002) {
    console.log("2003 ozone hole larger than 2002.");
    console.log("<answer>A</answer>");
  } else {
    console.log("2003 ozone hole NOT larger than 2002.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
